  const [status, setStatus] = useState("People loaded.");
  const [teamSection, setTeamSection] = useState<"directory" | "profiles" | "activity" | "work" | "capacity" | "communication">("directory");
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [avatarAuditFilter, setAvatarAuditFilter] = useState<"pending" | "all">("pending");
  const [avatarAudits, setAvatarAudits] = useState<AvatarAudit[]>([]);
  const deferredQuery = useDeferredValue(query);
  const assignmentByUserId = useMemo(() => new Map(assignments.map((item) => [item.user.id, item])), [assignments]);
