  const teams = useMemo(() => unique([...configuredDepartments.map((department) => department.defaultTeamName || "").filter(Boolean), ...users.map((user) => user.teamName || "").filter(Boolean)]), [configuredDepartments, users]);
  const normalizedTeamQuery = deferredQuery.trim().toLowerCase();
  const filteredUsers = useMemo(() => users.filter((member) => {
    if (!showArchived && member.archived) return false;
    if (roleFilter !== "all" && (member.workspaceRole || "member") !== roleFilter) return false;
    if (statusFilter !== "all" && (member.status || "available") !== statusFilter && activeLabel(member.lastSeenAt, member.lastActivityAt).toLowerCase() !== statusFilter) return false;
    const haystack = [member.username, member.employeeNumber, member.displayName, member.legalName, member.preferredName, member.email, ...(member.alternateEmails || []), member.phoneNumber, member.alternatePhoneNumber, member.title, member.department, member.teamName, member.managerName, member.employmentType, member.workLocation, member.statusMessage, ...(member.skills || [])].filter(Boolean).join(" ").toLowerCase();
    return haystack.includes(normalizedTeamQuery);
  }), [users, showArchived, roleFilter, statusFilter, normalizedTeamQuery]);
  const selectedUserIdSet = useMemo(() => new Set(selectedUserIds), [selectedUserIds]);
  const selectedUsers = useMemo(() => users.filter((item) => selectedUserIdSet.has(item.id)), [users, selectedUserIdSet]);
  const currentAssignment = assignmentByUserId.get(activeUserId);
