  const missingProfileUsers = users.filter((member) => !member.email || !member.legalName || !member.phoneNumber || !member.title || (departmentRequired && !member.department) || !member.teamName || ((capacityRequired || settings?.studioDepartmentCapacityMode !== "off") && !member.capacityHours) || !(member.skills || []).length);
  const selectedCapacity = selectedUsers.reduce((total, member) => total + (member.capacityHours || 0), 0);
  const selectedAssignedCards = selectedUsers.reduce((total, member) => total + (assignmentByUserId.get(member.id)?.cards.length || 0), 0);
